def _ad_wait_idle '{
  while(epics_get(AD["status_pv"]) != "Idle") {
	sleep(0.05)
	if(epics_get(AD["status_pv"]) == "Error") {
		filename = "pilatus_err_log"
		detState = epics_get("PIL8:cam1:DetectorState_RBV")
		detAcqStatus = epics_get("PIL8:cam1:Acquire")
		string array detFullFileName[256]
		detFullFileName = epics_get("PIL8:cam1:FullFileName_RBV")

		err = on(filename)
		if(err == -1){
			print("ERROR Opening File")
		}
		else {
			s = sprintf("%s State: %s FileName: %s \n", date(), detState, detFullFileName)
			print s
		}
#		epics_put(sprintf("%s:cam1:FileNumber", AD["prefix"]), AD["count"]-1)
		sleep(0.05)
  		epics_put(sprintf("%s:cam1:Acquire", AD["prefix"]), "Acquire")
		s = sprintf("%s State: %s FileName: %s \n", date(), detState, detFullFileName)
		print s

		off(filename)
		close(filename)
	}
  }
}'

